mapper.select:
select elrp.*, erp.actual_repayment_date , COALESCE(erp.actual_repayment_principal_amount, 0) + COALESCE(erp.actual_repayment_interes_amount, 0) as repaymentAmount, eic.document_date as invoiceDate, eic.tax_value as invoiceAmount from eg_long_repayment_plan elrp left join eg_repayment_plan erp on elrp.contract_code =erp.contract_code and elrp.receivable_date =erp.plan_date and erp.del_flag ='0' left join (select contract_code ,plan_repay_date,max(document_date) as document_date,sum(tax_value) as tax_value from eg_invoice_claim where del_flag='0' group by contract_code ,plan_repay_date ) eic on elrp.contract_code =eic.contract_code and elrp.receivable_date =eic.plan_repay_date where elrp.del_flag ='0'
and elrp.id in
#{item}
and elrp.long_register_id in
#{item}
order by elrp.long_receivable_number ,elrp.contract_code ,elrp.receivable_date
